// === Tab: mySketch ===



let num = 92; // how many rows and columns
let s = 0.7; // size of the dots
let reflex = 0.7; // how fast ir reacts when clicked. Range: [0, 1[
let aperture = 10; // how much it blurs

let bg = color(42); // background
let fg1 = color(99, 215, 236);// foreground
let fg2 = color(126, 197, 232);



function setup() {
  //createCanvas(800, 800); 


  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
  frameRate(30);

  aa = new Array(18);
  bb = new Array(aa.length);
  reset();
}

function mouseClicked() {
  reset();
}


let t = 0; // keeps the time

let aa; 
let bb;
let transition = 0;




function reset() {
  for (i = 0; i<bb.length; i++) {
    let v = random(1, 8);
    bb[i] = aa[i];
    aa[i] = random(2)<1?v:-v;
  }
  transition = 1;
}
function draw() {
  t+=0.0008; // enables time traveling

  background(bg);

  transition*=(1-reflex);


  for (v = 0; v<num; v++) {
    for (u = 0; u<num; u++) {
      let h = 42
        *sin((aa[0]*u-aa[1]*v)/num+4.2*aa[4]*t+aa[6])
        *cos((aa[2]*v+aa[3]*u )/num+aa[5]*t+aa[7]);

      let h2 = 42
        *sin((bb[0]*u-bb[1]*v)/num+4.2*bb[4]*t+bb[6])
        *cos((bb[2]*v+bb[3]*u )/num+bb[5]*t+bb[7]);
      h = lerp(h, h2, transition);

      let u1 = u/num*2-1;
      let v1 = v/num*2-1;

      let u2 = cos(t)*u1 + sin(t)*v1;
      let v2 = sin(t)*u1 - cos(t)*v1; 

      let u3 = u2/2+0.5;
      let v3 = v2/2+0.5;

      let x = u3*max(width, height);
      let y = v3*max(width, height);

      let a = x-y;
      let b = x+y;

      pushMatrix();
      translate(0, 0);
      translate(width/2, 0);
      let dist = 1.5-b/2/height-h/300;
      scale(atan(1/dist)*10);  // a little math
      translate(-width/2, -height/2.2);

      let blur = (1-dist)*aperture;
      fill(lerpColor(fg1, fg2, constrain(map(blur, -aperture/2, aperture/2, 0, 1), 0, 1)), // blend the colors
        min(s*255/max(sq(blur/2), 1), 128)); // add transparency

      translate(0, -h); // creates the waves
      ellipse(a/4+width/2, b/42+height/2, max(abs(blur), s), max(abs(blur), s));
      popMatrix();
    }
  }
}

